INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(113999, 'ruRU', '', '...а потом она разозлилась так, что превратила всех в... в...', 24330),
(114000, 'ruRU', '', 'ПРОКЛЯТЫХ ДУХОВ!', 24330),
(114001, 'ruRU', '', 'Ой, прости.', 24330),
(114002, 'ruRU', '', 'Я жду того дня, когда наши хозяева по-настоящему смогут перейти в этот мир. Ты видел лишь фрагменты, тени, слабейшее эхо. Спроси эфириалов, на что способно одно из таких проявлений.', 24330),
(114003, 'ruRU', '', 'Донесения указывают на то, что в Отмелях Обломков обитает исполинский краб. Предположительно, его клешни крепче стали! Мы могли бы выковать из них могучее оружие.', 24330),
(114004, 'ruRU', '', 'Погоди, это были просто обычные клешни краба, только побольше? Как не повезло.', 24330),
(114005, 'ruRU', '', 'Близость Пустоты здесь успокаивает. Меня использовали при жертвоприношении множества существ в подобном месте. Каждая смерть приближала нас к полному развращению этого мира.', 24330),
(114007, 'ruRU', '', 'Я с теплотой вспоминаю Тёмное Железо. Модгуд было так легко повлиять, настолько сильна была её ненависть. Представь её ярость, когда я бросил её на милость Дикого Молота в самый неподходящий момент. Меня очень легко потерять... запомни это.', 24330),
(114008, 'ruRU', '', 'В этом конфликте мы, возможно, столкнёмся с некоторыми из моих сородичей... перспектива, что меня радует. Их сила станет моей! Они заплатят за то, что было сделано со мной давным-давно.', 24330),
(114011, 'ruRU', '', 'Бог Глубин извивается в своей темнице, освобождаясь очень медленно. Тебе стоит поспешить и повергнуть падшего титана... впереди ждут битвы ещё более великие.', 24330),
(114021, 'ruRU', '', 'Интересная мутация древнего вида. Его панцирь почти неприступен. Почти...', 24330),
(114022, 'ruRU', '', 'Интересное слияние демонических видов. Интересно, есть ли ещё подобные ему?', 24330),
(114023, 'ruRU', '', 'Какое высокомерие, даже для долгоживущей эльфийки. Вкус её жизненной силы... изыскан.', 24330),
(114024, 'ruRU', '', 'Вот тот, кто лишь мельком увидел твою мрачную реальность. Это навеки искривило его разум.', 24330),
(114025, 'ruRU', '', 'Она заявляет, что знает будущее, но те, кто жил намного дольше её, знают истину. Её отчаянная попытка удержать контроль обрекает её народ.', 24330),
(114026, 'ruRU', '', 'Его час давно должен был настать. Истинный слуга падшего титана, он стремится к гибели всего сущего. Как будто это и впрямь спасло бы их от Пустоты.', 24330),
(114027, 'ruRU', '', '<короткий смешок>', 24330),
(114028, 'ruRU', '', '<злобный смех>', 24330),
(114029, 'ruRU', '', 'Развращённый труп дракона... насколько опасным он может оказаться?', 24330),
(114030, 'ruRU', '', 'Ещё один слуга с искажённым разумом, подданный Ксавия. Друиду следовало бы лучше владеть собственным разумом, не находишь?', 24330),
(114031, 'ruRU', '', 'Ходят слухи, что исполина, известного как Панцирная Пасть, видели прорубающим путь разрушения через Шепчущие Ивы!', 24330),
(114033, 'ruRU', '', 'Отлично сделано. Теперь хоть что-то останется, когда наг изгонят.', 24330),
(114034, 'ruRU', '', 'Забавно, что слабейший из нас может оказаться истинным победителем. Ктун, Йогг-Сарон, Йшарруж, и... что ж. Лишь одному суждено остаться, чтобы поглотить мир — так было задумано всегда.', 24330),
(114035, 'ruRU', '', 'Эй, братец! Тут кое-кто пришёл, чтобы...', 24330),
(114036, 'ruRU', '', 'Ой. Прости.', 24330),
(114037, 'ruRU', '', 'Привлечение эредаров было немалой победой для Саргераса. Ему отчаянно требовалось больше разумных существ в своём войске.', 24330),
(114040, 'ruRU', '', 'Они здесь, чтобы помочь нам найти маму и папу.', 24330),
(114044, 'ruRU', '', 'Величественная Митана была осквернена Кошмаром. Найди её и прекрати её мучения.', 24330),
(114045, 'ruRU', '', 'Ты отлично справился. Ткачи Снов перед тобой в долгу.', 24330),
(114062, 'ruRU', '', 'Что? Каллистия и Олотил здесь?', 24330),
(114063, 'ruRU', '', 'Я... я думал, мы потеряли их навсегда.', 24330),
(114064, 'ruRU', '', 'Поторопись, Тан! Давай найдём их!', 24330),
(114069, 'ruRU', '', 'Я кого-то выслеживаю... врата прорваны!', 24330),
(114071, 'ruRU', '', 'Я нашёл их!', 24330),
(114072, 'ruRU', '', 'Мама, папа скоро вернётся домой?', 24330),
(114073, 'ruRU', '', 'Да, малыш, он будет дома, ты и не заметишь.', 24330),
(114074, 'ruRU', '', 'Очень хорошо!', 24330),
(114081, 'ruRU', '', 'Демонов привлечёт сила, которую я призову, чтобы наложить чары на твоё оружие.', 24330),
(114082, 'ruRU', '', 'Используемые материалы крайне неустойчивы. Любое прерывание может обернуться катастрофой.', 24330),
(114083, 'ruRU', '', 'Я продолжу делать то, что умею лучше всего, если ты будешь держать этих демонов подальше от меня и моего стола для наложения чар.', 24330);
